                           fetchImports();
                           fetchFilters(); // Update filters with new data
                           setTimeout(() => setCurrentProcessId(null), 3000);
                         }
                       } catch (e) {}
                     }
                   });
                   push();
                 });
               }
               push();
             }
           });
