                                   <button onClick={createCampaign} className="btn-primary col-span-2">Disparar</button>
                               </div>
                           )}
                       </div>
                   </div>
               )}
            </div>
          )}

          {activeTab === 'whatsapp' && (
            <div className="flex h-full gap-6">
