                      const formData = new FormData();
                      formData.append('file', file);
                      try {
                        const res = await fetch('/start-processing', { method: 'POST', body: formData });
                        if (res.ok) {
                          const { processId } = await res.json();
                          setCurrentProcessId(processId);
