                                       <button onClick={() => setCampaignStep(1)} className="btn-secondary">Voltar</button>
                                       <button onClick={() => setCampaignStep(3)} className="btn-primary" disabled={selectedIds.size === 0}>Próximo ({selectedIds.size})</button>
                                   </div>
