                                     saveAiConfig({...aiConfig, knowledgeRules: newRules});
                                     setEditingRule(null);
                                 }} className="btn-primary">Salvar Regra</button>
                             </div>
                         </div>
                     </div>
                 ) : (
                     <div className="grid gap-4">
