    db.run('INSERT INTO consulta (id, filename, total, processed, status, start_time) VALUES (?, ?, ?, ?, ?, ?)', [processId, req.file.originalname, 0, 0, 'processing', new Date().toISOString()]);
    res.json({ processId });
