              {activeTab === 'companies' ? 'Base de Empresas' : 
               activeTab === 'campaigns' ? 'Gestão de Campanhas' : 
               activeTab === 'knowledge' ? 'Conhecimento IA' : activeTab}
            </h1>
          </div>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-slate-100 rounded-full">
              <div className={`w-2 h-2 rounded-full ${waSession.status==='connected'?'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]':'bg-rose-500'}`}></div>
              <span className="text-[10px] font-bold text-slate-500 uppercase">{waSession.status==='connected'?'Conectado':'Desconectado'}</span>
            </div>
          </div>
        </header>

        <div className="p-8 max-w-[1600px] mx-auto w-full flex-1">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-fade-in">
              {[{l:'Total Empresas',v:stats.total, i:FileSpreadsheet, c:'brand'},
                {l:'Sucesso Sefaz',v:stats.success, i:CheckCircle2, c:'emerald'},
                {l:'Erros Sefaz',v:stats.errors, i:AlertCircle, c:'rose'},
                {l:'Campanhas Ativas',v:campaigns.length, i:Rocket, c:'purple'}
