                <div key={i} className="card-premium p-6 card-hover border-slate-200/50">
                  <div className="flex justify-between items-start mb-4">
                    <div className={`p-3 bg-${s.c}-50 rounded-2xl text-${s.c}-600`}><s.i size={24} /></div>
                  </div>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">{s.l}</p>
                  <h3 className="text-3xl font-black text-slate-800 tracking-tight">{s.v}</h3>
