                        <td className="px-6 py-4"><span className="px-2 py-1 bg-brand-50 text-brand-600 rounded-lg font-bold">{i.total}</span></td>
                        <td className="px-6 py-4 text-right">
                          <button onClick={() => deleteImport(i.id)} className="p-2 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={18}/></button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
