          {activeTab === 'campaigns' && (
            <div className="space-y-6 animate-fade-in">
               {!isCreatingCampaign ? (
                 <>
                   <div className="flex justify-between items-center mb-2">
                     <div>
                       <h2 className="text-xl font-black text-slate-800 tracking-tight uppercase">Campanhas de Prospecção</h2>
                       <p className="text-xs text-slate-500 font-medium">Gerencie e acompanhe seus disparos automatizados.</p>
                     </div>
                     <button onClick={() => setIsCreatingCampaign(true)} className="btn-primary flex items-center gap-2 h-11">
                       <Plus size={20}/> 
                       <span>Nova Campanha</span>
                     </button>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
