                       <div key={c.id} onClick={() => { setViewingCampaign(c); fetchCampaignLeads(c.id); }} className="card-premium p-6 cursor-pointer group hover:border-brand-500/50 hover:shadow-xl hover:shadow-brand-500/5 transition-all border-slate-200/50 relative bg-white overflow-hidden">
                         <div className="absolute top-0 right-0 w-24 h-24 bg-brand-50 rounded-bl-full -mr-12 -mt-12 transition-all group-hover:scale-110"></div>
                         <button onClick={(e) => { e.stopPropagation(); deleteCampaign(c.id); }} className="absolute top-4 right-4 text-slate-200 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all z-10"><Trash2 size={18}/></button>

                         <div className="relative z-10">
                           <div className="flex items-center gap-3 mb-4">
                             <div className="w-10 h-10 bg-brand-600 rounded-xl flex items-center justify-center text-white"><Rocket size={20}/></div>
                             <h3 className="font-black text-slate-800 uppercase tracking-tight truncate flex-1">{c.name}</h3>
                           </div>

                           <p className="text-xs text-slate-500 mb-6 line-clamp-2 h-8">{c.description || 'Sem descrição.'}</p>

                           <div className="grid grid-cols-3 gap-1 p-1 bg-slate-50 rounded-xl overflow-hidden">
                             <div className="bg-white p-2 text-center rounded-lg shadow-sm">
                               <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">Total</p>
                               <p className="font-black text-slate-800 text-sm">{c.stats?.total || 0}</p>
                             </div>
                             <div className="bg-white p-2 text-center rounded-lg shadow-sm">
                               <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">Enviados</p>
                               <p className="font-black text-brand-600 text-sm">{c.stats?.sent || 0}</p>
                             </div>
                             <div className="bg-white p-2 text-center rounded-lg shadow-sm">
                               <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">Respostas</p>
                               <p className="font-black text-emerald-600 text-sm">{c.stats?.replied || 0}</p>
                             </div>
                           </div>

                           <div className="mt-4 flex justify-between items-center pt-4 border-t border-slate-100">
                             <span className="text-[10px] font-bold text-slate-400 uppercase">{new Date(c.created_at).toLocaleDateString()}</span>
                             <div className="flex items-center gap-1 text-brand-600 font-black text-[10px] uppercase group-hover:gap-2 transition-all">Ver Detalhes <ChevronRight size={12}/></div>
                           </div>
                         </div>
                       </div>
                     ))}
