                   {campaigns.length === 0 && (
                     <div className="card-premium p-20 text-center bg-white border-dashed border-slate-200">
                       <Rocket size={48} className="mx-auto text-slate-200 mb-4" />
                       <h3 className="text-xl font-bold text-slate-400">Nenhuma campanha criada.</h3>
                       <button onClick={() => setIsCreatingCampaign(true)} className="text-brand-600 font-bold mt-2 uppercase text-xs tracking-widest hover:underline">Criar agora</button>
                     </div>
