function decodeHTMLEntities(text) {
    if (!text) return '';
    const entities = {
        '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&apos;': "'",
        '&nbsp;': ' ', '&atilde;': 'ã', '&ccedil;': 'ç', '&iacute;': 'í',
        '&ocirc;': 'ô', '&otilde;': 'õ', '&uacute;': 'ú'
    };
    return text.replace(/&[a-z]+;/g, match => entities[match] || match);
}

