          const raw = company.telefone.replace(/\D/g, '');
          const target = raw.length < 12 ? '55' + raw : raw;
          const chatId = target + '@c.us';
          setActiveTab('whatsapp');
          setActiveChat(chatId);
          fetchMessages(chatId);
          setSelectedKanbanLead(null); // Close modal
