  // Handler to reset and open campaign wizard
  const handleOpenNewCampaign = () => {
      setNewCampaign({
          name: '',
          description: '',
          initialMessage: 'Olá, tudo bem? Vi que sua empresa possui pendências na SEFAZ e gostaria de ajudar.',
          aiPersona: DEFAULT_AI_PERSONA
