          )}

          {activeTab === 'whatsapp' && (
              <div className="flex h-[75vh] gap-4">
                  <div className="w-1/3 card-premium overflow-y-auto bg-white">
                      {chats.map(c => (
                          <div key={c.id} onClick={() => { setActiveChat(c.id); fetchMessages(c.id); }} className={`p-4 border-b cursor-pointer hover:bg-slate-50 ${activeChat === c.id ? 'bg-slate-100' : ''}`}>
                              <h4 className="font-bold text-sm truncate">{c.name || c.id}</h4>
