                                  <button onClick={() => setEditingRule({...editingRule, instructions: [...editingRule.instructions, { id: uuidv4(), content: '', type: 'simple', title: 'Info' }]})} className="text-brand-600 font-bold">+ Adicionar Diretriz</button>
