                              <div className="flex justify-end gap-3 border-t pt-4"><button onClick={() => setEditingRule(null)} className="btn-secondary">Cancelar</button><button onClick={() => { saveAiConfig({...aiConfig, knowledgeRules: [...aiConfig.knowledgeRules.filter(r => r.id !== editingRule.id), editingRule]}); setEditingRule(null); }} className="btn-primary px-10">Salvar Regra</button></div>
