                  ) : (
                      <div className="grid gap-4">
                          {aiConfig.knowledgeRules.map(r => (
                              <div key={r.id} className="card-premium p-6 flex justify-between items-start border-l-4 border-brand-500">
                                  <div><h4 className="font-bold text-lg mb-2">{r.motivoSituacao}</h4>{r.instructions.map((inst, i) => <p key={i} className="text-sm text-slate-600 flex gap-2"><CheckCircle2 size={14} className="mt-0.5 text-emerald-500"/> {inst.content}</p>)}</div>
                                  <div className="flex gap-1"><button onClick={() => setEditingRule(r)} className="p-2 text-slate-400 hover:text-brand-600"><Edit size={18}/></button><button onClick={() => saveAiConfig({...aiConfig, knowledgeRules: aiConfig.knowledgeRules.filter(x => x.id !== r.id)})} className="p-2 text-slate-400 hover:text-rose-600"><Trash2 size={18}/></button></div>
                              </div>
                          ))}
                      </div>
                  )}
              </div>
          )}

          {activeTab === 'settings' && (
              <div className="max-w-2xl mx-auto card-premium p-8 space-y-6">
                  <h3 className="font-bold mb-4 flex gap-2"><Bot/> Persona Global</h3>
                  <textarea className="input-premium h-48" value={aiConfig.persona} onChange={e => setAiConfig({...aiConfig, persona: e.target.value})} placeholder="Defina como a IA deve agir..." />
                  <button onClick={() => saveAiConfig(aiConfig)} className="btn-primary w-full"><Save size={18}/> Salvar Persona</button>
              </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

