                        className={`w-10 h-5 rounded-full flex items-center transition-all p-1 ${aiConfig.aiActive ? 'bg-emerald-500 justify-end' : 'bg-slate-600 justify-start'}`}
                    >
                        <div className="w-3 h-3 bg-white rounded-full shadow-md"></div>
                    </button>
                </div>
            </div>
        )}
      </aside>

