const normalizeText = (text) => {
    if (!text) return '';
    return text.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
};

const client = new Client({
  authStrategy: new LocalAuth({ dataPath: path.join(DATA_DIR, 'whatsapp_auth') }),
