});

client.on('ready', () => { 
    clientReady = true; 
    addLog('success', 'WhatsApp: Cliente conectado e pronto!');
});

client.on('message', async (msg) => {
    if (msg.fromMe || msg.from.includes('status@broadcast') || msg.from.includes('@g.us')) return;

    addLog('message', `Recebido de ${msg.from}: "${msg.body.substring(0, 30)}..."`);

    if (!aiConfig.aiActive) return;

    let waId = msg.from;
    let cleanSenderPhone = msg.from.split('@')[0].replace(/\D/g, '');

    db.get(`SELECT * FROM resultado WHERE (wa_id = ? OR wa_id = ? OR telefone LIKE ? OR telefone = ?) AND ai_active = 1 ORDER BY id DESC LIMIT 1`, 
           [waId, waId.replace('@lid', '@c.us'), `%${cleanSenderPhone.slice(-8)}`, cleanSenderPhone], async (err, company) => {
            if (err) return addLog('error', `Erro DB: ${err.message}`);

            if (!company) {
                addLog('info', `AI: Contato ${cleanSenderPhone} não identificado no banco.`);
                return;
            }

            addLog('ai', `Lead identificado: ${company.razao_social}. Gerando resposta...`);

            let ruleInstructions = "";
            if (company.motivo_situacao_cadastral && aiConfig.knowledgeRules) {
                const leadMotivoNorm = normalizeText(company.motivo_situacao_cadastral);
                const matchedRule = aiConfig.knowledgeRules.find(r => {
                    if (!r.isActive || !r.motivoSituacao) return false;
                    const ruleMotivoNorm = normalizeText(r.motivoSituacao);
                    return leadMotivoNorm.includes(ruleMotivoNorm) || ruleMotivoNorm.includes(leadMotivoNorm);
                });
                if (matchedRule) {
                    addLog('ai', `Conhecimento: Aplicando regra para "${matchedRule.motivoSituacao}"`);
                    ruleInstructions = `\n--- REGRAS DA BASE ---\n`;
                    matchedRule.instructions.forEach(inst => { ruleInstructions += `- ${inst.content}\n`; });
                }
            }

            const strictInstruction = `${aiConfig.persona}\n${ruleInstructions}\nEmpresa: ${company.razao_social} | Motivo: ${company.motivo_situacao_cadastral}`;

            try {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                const response = await ai.models.generateContent({ 
                    model: aiConfig.model || 'gemini-3-flash-preview',
                    contents: [{ parts: [{ text: msg.body }] }],
                    config: { systemInstruction: strictInstruction, temperature: aiConfig.temperature || 0.6 }
                });

                const finalText = response.text;
                if (finalText) {
                    await msg.reply(finalText);
                    addLog('success', `AI: Resposta enviada para ${company.razao_social}.`);
                    db.run(`UPDATE resultado SET campaign_status = 'replied', last_contacted = ? WHERE id = ?`, [new Date().toISOString(), company.id]);
                }
            } catch (error) { 
                addLog('error', `AI: Falha na geração: ${error.message}`);
            }
        }
    );
});

client.initialize().catch(err => addLog('error', `WA: Falha ao iniciar: ${err.message}`));

function startCampaignSending(campaignId, message) {
    addLog('info', `Campanha: Iniciando fila para ID ${campaignId}`);
    const processQueue = () => {
        db.get(`SELECT * FROM resultado WHERE campaign_id = ? AND (campaign_status = 'queued' OR campaign_status = 'pending') LIMIT 1`, [campaignId], async (err, lead) => {
            if (!lead) {
                addLog('success', `Campanha: Envio finalizado.`);
                return;
            }
            if (!clientReady) return setTimeout(processQueue, 5000);

            try {
                const target = lead.telefone.replace(/\D/g, '').startsWith('55') ? lead.telefone.replace(/\D/g, '') : '55' + lead.telefone.replace(/\D/g, '');
                await client.sendMessage(target + "@c.us", message);
                addLog('success', `Enviado para: ${lead.razao_social}`);
                db.run(`UPDATE resultado SET campaign_status = 'sent', last_contacted = ? WHERE id = ?`, [new Date().toISOString(), lead.id], () => {
                    setTimeout(processQueue, Math.random() * 5000 + 8000);
                });
            } catch (e) {
                addLog('error', `Falha envio ${lead.telefone}: ${e.message}`);
                db.run(`UPDATE resultado SET campaign_status = 'error' WHERE id = ?`, [lead.id], () => setTimeout(processQueue, 3000));
            }
        });
    };
    processQueue();
}

