    );
});

client.initialize().catch(err => addLog('error', `WhatsApp: Falha ao inicializar: ${err.message}`));

function startCampaignSending(campaignId, message) {
    addLog('info', `Campanha: Iniciando disparos para ID ${campaignId}`);
    const processQueue = () => {
        db.get(`SELECT * FROM resultado WHERE campaign_id = ? AND (campaign_status = 'queued' OR campaign_status = 'pending') LIMIT 1`, [campaignId], async (err, lead) => {
            if (!lead) {
                addLog('success', `Campanha: Todos os leads processados.`);
                return;
            }
            if (!clientReady) return setTimeout(processQueue, 5000);

            try {
                const raw = lead.telefone.replace(/\D/g, '');
                const target = raw.startsWith('55') ? raw : '55' + raw;
                await client.sendMessage(target + "@c.us", message);
                addLog('success', `Mensagem enviada para ${lead.razao_social} (${target})`);
                db.run(`UPDATE resultado SET campaign_status = 'sent', last_contacted = ? WHERE id = ?`, [new Date().toISOString(), lead.id], () => {
                    setTimeout(processQueue, Math.floor(Math.random() * 5000) + 7000);
                });
            } catch (e) {
                addLog('error', `Falha ao enviar para ${lead.telefone}: ${e.message}`);
                db.run(`UPDATE resultado SET campaign_status = 'error' WHERE id = ?`, [lead.id], () => setTimeout(processQueue, 3000));
            }
        });
    };
    processQueue();
}

