// --- Subcomponentes de Estilo ---

const Badge = ({ children, variant = 'default' }: { children: React.ReactNode, variant?: string }) => {
  const styles: Record<string, string> = {
    default: 'bg-slate-100 text-slate-600 border-slate-200',
    success: 'bg-emerald-50 text-emerald-700 border-emerald-100',
    warning: 'bg-amber-50 text-amber-700 border-amber-100',
    danger: 'bg-rose-50 text-rose-700 border-rose-100',
    brand: 'bg-brand-50 text-brand-700 border-brand-100',
    whatsapp: 'bg-emerald-500 text-white border-transparent'
  };
  return (
    <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold border ${styles[variant] || styles.default}`}>
      {children}
    </span>
  );
};

const SystemLogTerminal = ({ logs }: { logs: any[] }) => {
    const scrollRef = useRef<HTMLDivElement>(null);
    useEffect(() => {
        if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }, [logs]);

    const getIcon = (level: string) => {
        switch(level) {
            case 'ai': return <Bot size={14} className="text-brand-400" />;
            case 'message': return <MessageCircle size={14} className="text-emerald-400" />;
            case 'error': return <AlertCircle size={14} className="text-rose-400" />;
            case 'success': return <CheckCircle2 size={14} className="text-emerald-500" />;
            default: return <Terminal size={14} className="text-slate-400" />;
        }
    };

    return (
        <div className="card-premium bg-slate-950 border-slate-800 flex flex-col h-full overflow-hidden shadow-2xl">
            <div className="bg-slate-900 px-4 py-3 border-b border-slate-800 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="flex gap-1.5">
                        <div className="w-3 h-3 rounded-full bg-rose-500/80"></div>
                        <div className="w-3 h-3 rounded-full bg-amber-500/80"></div>
                        <div className="w-3 h-3 rounded-full bg-emerald-500/80"></div>
                    </div>
                    <h3 className="text-xs font-mono font-bold text-slate-400 flex items-center gap-2 uppercase tracking-widest ml-2">
                        <Terminal size={14} /> Sistema de Logs IA
                    </h3>
                </div>
                <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                    <span className="text-[10px] font-mono text-emerald-500/70 uppercase">Live Sync</span>
                </div>
            </div>
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 font-mono text-[11px] space-y-2 custom-scrollbar bg-black/20">
                {logs.length === 0 && <p className="text-slate-700 italic flex items-center gap-2"><RefreshCw size={12} className="animate-spin"/> Aguardando atividades do servidor...</p>}
                {logs.slice().reverse().map((log) => (
                    <div key={log.id} className="flex gap-3 border-l border-slate-800 pl-3 py-1 group hover:bg-white/5 transition-colors border-b border-white/[0.02]">
                        <span className="text-slate-600 shrink-0 tabular-nums">{new Date(log.timestamp).toLocaleTimeString([], { hour12: false })}</span>
                        <div className="flex items-start gap-2 flex-1 min-w-0">
                            <span className="shrink-0 mt-0.5">{getIcon(log.level)}</span>
                            <span className={`break-words ${
                                log.level === 'error' ? 'text-rose-400' : 
                                log.level === 'success' ? 'text-emerald-400' :
                                log.level === 'ai' ? 'text-brand-300' :
                                log.level === 'message' ? 'text-emerald-200 font-bold' : 'text-slate-300'
                            }`}>
                                <span className="opacity-50 mr-1">[{log.level.toUpperCase()}]</span>
                                {log.message}
                            </span>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

// --- Main App Component ---

const App: React.FC = () => {
  // Navigation & UI State
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Data State
  const [companies, setCompanies] = useState<CompanyResult[]>([]);
  const [systemLogs, setSystemLogs] = useState<any[]>([]);
  const [waSession, setWaSession] = useState<WhatsAppSession>({ status: 'disconnected' });
  const [filters, setFilters] = useState({ municipio: 'Todos', motivo: 'Todos', aiStatus: 'Todos' });
  const [uniqueFilters, setUniqueFilters] = useState({ municipios: [] as string[], motivos: [] as string[] });

  // AI & Knowledge State
  const [aiConfig, setAiConfig] = useState<AIConfig>({
    model: 'gemini-3-flash-preview',
    provider: 'gemini',
    apiKeys: { gemini: '', groq: '' },
    persona: DEFAULT_AI_PERSONA,
    knowledgeRules: DEFAULT_KNOWLEDGE_RULES,
    temperature: 0.7,
    aiActive: true
  });

  const [editingRule, setEditingRule] = useState<KnowledgeRule | null>(null);

  // --- API Methods ---

  const fetchData = async () => {
    setIsRefreshing(true);
    try {
        const [compRes, configRes, filtersRes] = await Promise.all([
            fetch('/get-all-results'),
            fetch('/api/config'),
            fetch('/api/unique-filters')
        ]);

        if (compRes.ok) setCompanies(await compRes.json());
        if (configRes.ok) setAiConfig(await configRes.json());
        if (filtersRes.ok) setUniqueFilters(await filtersRes.json());
    } catch (e) { console.error(e); }
    finally { setIsRefreshing(false); }
  };

  const fetchLogs = async () => {
      try {
          const res = await fetch('/api/system-logs');
          if (res.ok) setSystemLogs(await res.json());
      } catch (e) {}
  };

  const fetchWaStatus = async () => {
      try {
          const res = await fetch('/api/whatsapp/status');
          if (res.ok) setWaSession(await res.json());
      } catch (e) {}
  };

  const saveAiConfig = async (newConfig: AIConfig) => {
      try {
          const res = await fetch('/api/config/ai-rules', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(newConfig)
          });
          if (res.ok) setAiConfig(newConfig);
      } catch (e) { alert('Erro ao salvar config'); }
  };

  const toggleLeadAI = async (id: string, current: boolean) => {
      try {
          const res = await fetch('/api/leads/toggle-ai', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ id, active: !current })
          });
          if (res.ok) {
              setCompanies(prev => prev.map(c => c.id === id ? { ...c, aiActive: !current } : c));
          }
      } catch (e) {}
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(() => {
        fetchLogs();
        fetchWaStatus();
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  // --- Computed Values & Statistics ---

  const filteredCompanies = useMemo(() => {
    return companies.filter(c => {
