if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });

// --- Configuração Multer para Upload ---
const upload = multer({ dest: path.join(DATA_DIR, 'uploads/') });

// --- Sistema de Logs para Monitoramento ---
let systemLogs = [];
const addLog = (level, message) => {
    const log = { id: uuidv4(), timestamp: Date.now(), level, message };
    systemLogs.unshift(log);
    if (systemLogs.length > 50) systemLogs.pop();
    console.log(`[${level.toUpperCase()}] ${message}`);
};

const db = new sqlite3.Database(DB_PATH);

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS imports (
    id TEXT PRIMARY KEY,
    filename TEXT,
    date TEXT,
    total INTEGER,
    status TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS campaign (
    id TEXT PRIMARY KEY,
    name TEXT,
    description TEXT,
    initial_message TEXT,
    ai_persona TEXT,
    status TEXT,
    created_at TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS resultado (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    import_id TEXT,
    campaign_id TEXT,
    inscricao_estadual TEXT,
    cnpj TEXT,
    razao_social TEXT,
    nome_fantasia TEXT,
    municipio TEXT,
    telefone TEXT,
    wa_id TEXT,
    situacao_cadastral TEXT,
    motivo_situacao_cadastral TEXT,
    data_situacao_cadastral TEXT,
    nome_contador TEXT,
    status TEXT,
    campaign_status TEXT DEFAULT 'pending',
    last_contacted TEXT,
    ai_active INTEGER DEFAULT 1,
    FOREIGN KEY(import_id) REFERENCES imports(id)
  )`);
});

let aiConfig = {
  provider: 'gemini',
  apiKeys: { gemini: '', groq: '' },
  model: 'gemini-3-flash-preview',
  persona: 'Você é um assistente útil.',
  knowledgeRules: [], 
  temperature: 0.7,
  aiActive: true
};

if (fs.existsSync(AI_CONFIG_PATH)) {
    try {
        const savedConfig = JSON.parse(fs.readFileSync(AI_CONFIG_PATH, 'utf8'));
        aiConfig = { ...aiConfig, ...savedConfig };
    } catch (e) { console.error(e); }
}

// --- WhatsApp Client ---
const client = new Client({
  authStrategy: new LocalAuth({ dataPath: path.join(DATA_DIR, 'whatsapp_auth') }),
  puppeteer: {
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  },
  webVersionCache: {
    type: "remote",
    remotePath: "https://raw.githubusercontent.com/wppconnect-team/wa-version/main/html/2.2412.54.html",
  }
});

let qrCodeData = null;
let clientReady = false;

client.on('qr', (qr) => {
    addLog('info', 'WhatsApp: Novo QR Code gerado.');
    QRCode.toDataURL(qr, (err, url) => qrCodeData = url);
});

client.on('ready', () => { 
    clientReady = true; 
    addLog('success', 'WhatsApp: Conectado!');
});

client.on('message', async (msg) => {
    if (msg.fromMe || msg.from.includes('status@broadcast') || msg.from.includes('@g.us')) return;
    addLog('message', `Mensagem de ${msg.from}: ${msg.body.substring(0, 20)}...`);

    if (!aiConfig.aiActive) return;

    db.get(`SELECT * FROM resultado WHERE wa_id = ? OR telefone LIKE ? LIMIT 1`, 
           [msg.from, `%${msg.from.split('@')[0].slice(-8)}`], async (err, lead) => {
        if (!lead || !lead.ai_active) return;

        // Lógica de IA... (simplificada para o XML)
        addLog('ai', `IA processando resposta para ${lead.razao_social}`);
    });
});

client.initialize();

