            id: r.id.toString(),
            inscricaoEstadual: r.inscricao_estadual,
            razaoSocial: r.razao_social,
            nomeFantasia: r.nome_fantasia,
            situacaoCadastral: r.situacao_cadastral,
            motivoSituacao: r.motivo_situacao_cadastral,
            campaignStatus: r.campaign_status || 'pending',
            aiActive: r.ai_active === 1
        })));
    });
});

app.get('/get-imports', (req, res) => {
    db.all('SELECT * FROM imports ORDER BY date DESC', (err, rows) => res.json(rows));
});

// Mock de processamento para UI
app.post('/start-processing', upload.single('file'), (req, res) => {
    const processId = uuidv4();
    const importId = uuidv4();
    addLog('info', `Importação iniciada: ${req.file.originalname}`);

    db.run(`INSERT INTO imports (id, filename, date, total, status) VALUES (?, ?, ?, ?, ?)`,
           [importId, req.file.originalname, new Date().toISOString(), 100, 'processing']);

    // Simulação de processamento
    let count = 0;
    const interval = setInterval(() => {
        count += 5;
        if (count >= 100) {
            clearInterval(interval);
            db.run(`UPDATE imports SET status = 'completed' WHERE id = ?`, [importId]);
            addLog('success', `Importação finalizada: ${req.file.originalname}`);
        }
    }, 1000);

    res.json({ processId });
});

app.get('/api/whatsapp/status', (req, res) => res.json({ status: clientReady ? 'connected' : 'disconnected', qr: qrCodeData }));

app.get('/api/whatsapp/chats', async (req, res) => {
    if (!clientReady) return res.json([]);
    const chats = await client.getChats();
    res.json(chats.map(c => ({ id: c.id._serialized, name: c.name, unreadCount: c.unreadCount, timestamp: c.timestamp, lastMessage: c.lastMessage?.body })));
});

app.get('/api/whatsapp/messages/:chatId', async (req, res) => {
    if (!clientReady) return res.json([]);
    const chat = await client.getChatById(req.params.chatId);
    const msgs = await chat.fetchMessages({ limit: 50 });
    res.json(msgs.map(m => ({ id: m.id.id, body: m.body, fromMe: m.fromMe, timestamp: m.timestamp })));
});

app.get('/api/unique-filters', (req, res) => {
    db.all('SELECT DISTINCT municipio FROM resultado', (err, rows) => {
        const municipios = rows.map(r => r.municipio).filter(m => !!m);
        db.all('SELECT DISTINCT motivo_situacao_cadastral FROM resultado', (err2, rows2) => {
            const motivos = rows2.map(r => r.motivo_situacao_cadastral).filter(m => !!m);
            res.json({ municipios, motivos });
        });
    });
});

app.listen(port, () => addLog('info', `Servidor iniciado na porta ${port}`));

