import './polyfill.js';
import 'dotenv/config';
import express from 'express';
import { createRequire } from 'module';
const require = createRequire(import.meta.url);
import path from 'path';
import { fileURLToPath } from 'url';
import cors from 'cors';
import pkg from 'whatsapp-web.js';
const { Client, LocalAuth } = pkg;
import QRCode from 'qrcode';
import fs from 'fs';
import { GoogleGenAI } from "@google/genai";
import { Groq } from 'groq-sdk';
import multer from 'multer';
import sqlite3 from 'sqlite3';
import { v4 as uuidv4 } from 'uuid';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const port = 3000;

const DATA_DIR = process.env.DATA_PATH || path.join(__dirname, 'data');
const DB_PATH = path.join(DATA_DIR, 'consultas.db');
const AI_CONFIG_PATH = path.join(DATA_DIR, 'ai-config.json');

if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });

const upload = multer({ dest: path.join(DATA_DIR, 'uploads/') });

let systemLogs = [];
const addLog = (level, message) => {
    const log = { id: uuidv4(), timestamp: Date.now(), level, message };
    systemLogs.unshift(log);
    if (systemLogs.length > 50) systemLogs.pop();
    console.log(`[${level.toUpperCase()}] ${message}`);
};

const db = new sqlite3.Database(DB_PATH);

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS imports (
    id TEXT PRIMARY KEY,
    filename TEXT,
    date TEXT,
    total INTEGER,
    status TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS campaign (
    id TEXT PRIMARY KEY,
    name TEXT,
    description TEXT,
    initial_message TEXT,
    ai_persona TEXT,
    status TEXT,
    created_at TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS resultado (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    import_id TEXT,
    campaign_id TEXT,
    inscricao_estadual TEXT,
    cnpj TEXT,
    razao_social TEXT,
    nome_fantasia TEXT,
    municipio TEXT,
    telefone TEXT,
    wa_id TEXT,
    situacao_cadastral TEXT,
    motivo_situacao_cadastral TEXT,
    data_situacao_cadastral TEXT,
    nome_contador TEXT,
    status TEXT,
    campaign_status TEXT DEFAULT 'pending',
    last_contacted TEXT,
    ai_active INTEGER DEFAULT 1,
    FOREIGN KEY(import_id) REFERENCES imports(id)
  )`);
});

let aiConfig = {
  provider: 'gemini',
  apiKeys: { gemini: '', groq: '' },
  model: 'gemini-3-flash-preview',
  persona: 'Você é um assistente útil.',
  knowledgeRules: [], 
  temperature: 0.7,
  aiActive: true
};

if (fs.existsSync(AI_CONFIG_PATH)) {
    try {
        const savedConfig = JSON.parse(fs.readFileSync(AI_CONFIG_PATH, 'utf8'));
        aiConfig = { ...aiConfig, ...savedConfig };
    } catch (e) { console.error(e); }
}

const client = new Client({
  authStrategy: new LocalAuth({ dataPath: path.join(DATA_DIR, 'whatsapp_auth') }),
  puppeteer: {
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  },
  webVersionCache: {
    type: "remote",
    remotePath: "https://raw.githubusercontent.com/wppconnect-team/wa-version/main/html/2.2412.54.html",
  }
});

let qrCodeData = null;
let clientReady = false;

client.on('qr', (qr) => {
    QRCode.toDataURL(qr, (err, url) => qrCodeData = url);
    addLog('info', 'WhatsApp: Novo QR Code pronto para leitura.');
});

client.on('ready', () => { 
    clientReady = true; 
    addLog('success', 'WhatsApp: Conectado com sucesso!');
});

client.on('message', async (msg) => {
    if (msg.fromMe || msg.from.includes('status@broadcast') || msg.from.includes('@g.us')) return;
    addLog('message', `Nova mensagem de ${msg.from}`);
});

client.initialize();

app.use(cors());
app.use(express.json());

app.get('/api/system-logs', (req, res) => res.json(systemLogs));
app.get('/api/config', (req, res) => res.json(aiConfig));
app.post('/api/config/ai-rules', (req, res) => {
    aiConfig = { ...aiConfig, ...req.body };
    fs.writeFileSync(AI_CONFIG_PATH, JSON.stringify(aiConfig, null, 2));
    res.json({ success: true, config: aiConfig });
});

app.get('/get-all-results', (req, res) => {
    db.all('SELECT * FROM resultado ORDER BY id DESC', (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json(rows.map(r => ({
            ...r,
            id: r.id.toString(),
            inscricaoEstadual: r.inscricao_estadual,
            razaoSocial: r.razao_social,
            nomeFantasia: r.nome_fantasia,
            situacaoCadastral: r.situacao_cadastral,
            motivoSituacao: r.motivo_situacao_cadastral,
            campaignStatus: r.campaign_status || 'pending',
            aiActive: r.ai_active === 1
        })));
    });
});

app.post('/api/leads/toggle-ai', (req, res) => {
    const { id, active } = req.body;
