    if (!clientReady) return res.json([]);
    const chats = await client.getChats();
    res.json(chats.map(c => ({ id: c.id._serialized, name: c.name, unreadCount: c.unreadCount, timestamp: c.timestamp, lastMessage: c.lastMessage?.body })));
