    const { chatId, message } = req.body;
    await client.sendMessage(chatId, message);
    res.json({ success: true });
});

app.get('/api/unique-filters', (req, res) => {
    db.all('SELECT DISTINCT municipio FROM resultado', (err, rows) => {
        const municipios = rows ? rows.map(r => r.municipio).filter(m => !!m) : [];
        db.all('SELECT DISTINCT motivo_situacao_cadastral FROM resultado', (err2, rows2) => {
            const motivos = rows2 ? rows2.map(r => r.motivo_situacao_cadastral).filter(m => !!m) : [];
            res.json({ municipios, motivos });
        });
