    if (!text) return '';
    return text.split('Endereço de Correspondência')[0].split('Endereço:')[0].trim();
};

const formatTime = (timestamp: number) => {
    if (!timestamp) return '';
    return new Date(timestamp * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
};

