                                        <div className="flex gap-2 mt-0.5">
                                            <span className="text-[9px] font-mono text-slate-400 bg-slate-50 px-1 rounded">{lead.cnpj}</span>
                                            <span className="text-[9px] font-bold text-slate-400">{lead.municipio}</span>
